package home

import (
	"encoding/base64"
	"strconv"
	"strings"
)

// Two charts, merged pull requests and reviews per month, each stacked by
// repository. A realm cannot read GitHub, so each chart's numbers live in a
// section, "activity" and "reviewactivity", and scripts/activity.py prints the
// Set commands that refresh them. A section reads, lines split by ";":
//
//	title merged pull requests
//	subtitle per month, on public gno.land repositories
//	series gnolang/gno,gnodaokit,Others,Peer Dev
//	scale Peer Dev,10,commits
//	outline gnolang/gno pull requests opened
//	updated 2026-09-24
//	2025-07 4 0 1 48 | 3
//
// Each month row carries one count per series. A scaled series counts another
// unit: its bars are drawn at one step per 10, and it stays out of the totals.
// The count after "|" draws a striped bar in the first series' colour beside
// the stack.

const (
	activitySlot       = "activity"
	reviewActivitySlot = "reviewactivity"
	chartWidth         = 720
	chartX             = 24
	maxBar             = 90
	scaledFill         = "#fbbf24"
	othersFill         = "#94a3b8"
)

var (
	monthNames = []string{"Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"}
	// A repository keeps its colour in both charts; one not listed here takes
	// a spare colour picked from its name.
	repoFills = map[string]string{
		"gnolang/gno":        "#3ddc97",
		"gno-onboarding-bot": "#7aa2ff",
		"gnodaokit":          "#c084fc",
		"awesome-gno":        "#f472b6",
		"gnolove":            "#2dd4bf",
	}
	spareFills = []string{"#fb923c", "#a3e635", "#38bdf8", "#e879f9"}
)

type month struct {
	label   string // "Jul", or "Jan 26" where a year starts
	counts  []int
	outline int
}

type activity struct {
	noun      string
	subtitle  string
	series    []string
	scaled    string // the series counted in another unit, or ""
	scaleDiv  int
	scaleUnit string
	outline   string // the striped bar's legend, or ""
	updated   string // "24 Sep 2026", the day the numbers were counted
	months    []month
}

// parseActivity reads a chart section; a malformed line is skipped.
func parseActivity(spec string) activity {
	var a activity
	for _, line := range strings.Split(strings.ReplaceAll(spec, "\n", ";"), ";") {
		line = strings.TrimSpace(line)
		switch {
		case strings.HasPrefix(line, "title "):
			a.noun = strings.TrimSpace(line[6:])
		case strings.HasPrefix(line, "subtitle "):
			a.subtitle = strings.TrimSpace(line[9:])
		case strings.HasPrefix(line, "series "):
			for _, s := range strings.Split(line[7:], ",") {
				a.series = append(a.series, strings.TrimSpace(s))
			}
		case strings.HasPrefix(line, "scale "):
			parts := strings.Split(line[6:], ",")
			if len(parts) != 3 {
				continue
			}
			div, err := strconv.Atoi(strings.TrimSpace(parts[1]))
			if err != nil || div < 1 {
				continue
			}
			a.scaled, a.scaleDiv, a.scaleUnit = strings.TrimSpace(parts[0]), div, strings.TrimSpace(parts[2])
		case strings.HasPrefix(line, "outline "):
			a.outline = strings.TrimSpace(line[8:])
		case strings.HasPrefix(line, "updated "):
			a.updated = formatDay(strings.TrimSpace(line[8:]))
		default:
			if m, ok := parseMonth(line, len(a.series), len(a.months) == 0); ok {
				a.months = append(a.months, m)
			}
		}
	}
	return a
}

func parseMonth(line string, width int, first bool) (month, bool) {
	fields := strings.Fields(line)
	if len(fields) < 1 || len(fields[0]) != 7 || fields[0][4] != '-' {
		return month{}, false
	}
	m, err := strconv.Atoi(fields[0][5:])
	if err != nil || m < 1 || m > 12 {
		return month{}, false
	}
	out := month{label: monthNames[m-1]}
	if m == 1 || first {
		out.label += " " + fields[0][2:4]
	}
	counts := fields[1:]
	if n := len(counts); n >= 2 && counts[n-2] == "|" {
		v, err := strconv.Atoi(counts[n-1])
		if err != nil || v < 0 {
			return month{}, false
		}
		out.outline, counts = v, counts[:n-2]
	}
	if len(counts) != width || width == 0 {
		return month{}, false
	}
	for _, f := range counts {
		n, err := strconv.Atoi(f)
		if err != nil || n < 0 {
			return month{}, false
		}
		out.counts = append(out.counts, n)
	}
	return out, true
}

// formatDay turns 2026-09-24 into "24 Sep 2026", or "" when it is not a date.
func formatDay(s string) string {
	if len(s) != 10 || s[4] != '-' || s[7] != '-' {
		return ""
	}
	m, err1 := strconv.Atoi(s[5:7])
	d, err2 := strconv.Atoi(s[8:])
	if err1 != nil || err2 != nil || m < 1 || m > 12 || d < 1 || d > 31 {
		return ""
	}
	return strconv.Itoa(d) + " " + monthNames[m-1] + " " + s[:4]
}

func (a activity) fill(i int) string {
	name := a.series[i]
	switch name {
	case "Others":
		return othersFill
	case a.scaled:
		return scaledFill
	}
	if f, ok := repoFills[name]; ok {
		return f
	}
	sum := 0
	for j := 0; j < len(name); j++ {
		sum += int(name[j])
	}
	return spareFills[sum%len(spareFills)]
}

// drawn returns how many steps series i takes in the bar, rounding a scaled
// count up so a quiet month still shows.
func (a activity) drawn(i, n int) int {
	if a.series[i] == a.scaled {
		return (n + a.scaleDiv - 1) / a.scaleDiv
	}
	return n
}

// renderChart draws a chart section as a markdown image, or "" when it holds
// no month.
func renderChart(slot string) string {
	a := parseActivity(Get(slot))
	if len(a.months) == 0 || a.noun == "" {
		return ""
	}
	totals := make([]int, len(a.series))
	peak, sum, outlined := 1, 0, 0
	for _, m := range a.months {
		outlined += m.outline
		if m.outline > peak {
			peak = m.outline
		}
		steps := 0
		for i, n := range m.counts {
			totals[i] += n
			steps += a.drawn(i, n)
			if a.series[i] != a.scaled {
				sum += n
			}
		}
		if steps > peak {
			peak = steps
		}
	}

	// Legend entries flow left to right and wrap, so the chart sits below them.
	var b, items strings.Builder
	x, y := chartX, 96
	for i, s := range a.series {
		label := s + " " + strconv.Itoa(totals[i])
		if s == a.scaled {
			label += " " + a.scaleUnit + ", drawn 1 per " + strconv.Itoa(a.scaleDiv)
		}
		w := 24 + len(label)*7
		if x+w > chartWidth-chartX {
			x, y = chartX, y+22
		}
		rect(&items, x, y-10, 12, 12, 0, a.fill(i))
		text(&items, x+18, y, "s", "#ffffff", label)
		x += w + 12
	}
	if a.outline != "" {
		label := a.outline + " " + strconv.Itoa(outlined)
		w := 24 + len(label)*7
		if x+w > chartWidth-chartX {
			x, y = chartX, y+22
		}
		rect(&items, x, y-10, 12, 12, 0, "url(#o)")
		text(&items, x+18, y, "s", "#ffffff", label)
	}
	baseline := y + 30 + maxBar
	height := baseline + 34

	sh, sw := strconv.Itoa(height), strconv.Itoa(chartWidth)
	b.WriteString(`<svg xmlns="http://www.w3.org/2000/svg" width="` + sw + `" height="` + sh + `" viewBox="0 0 ` + sw + ` ` + sh + `">`)
	b.WriteString("<style>.h{font:700 26px sans-serif}.s{font:13px sans-serif}" +
		".n{font:600 11px sans-serif;text-anchor:middle}.m{font:11px sans-serif;text-anchor:middle}" +
		".u{font:12px sans-serif;text-anchor:end}</style>")
	b.WriteString(`<defs><pattern id="o" width="5" height="5" patternUnits="userSpaceOnUse" patternTransform="rotate(45)">` +
		`<rect width="2" height="5" fill="` + repoFills["gnolang/gno"] + `"/></pattern></defs>`)
	rect(&b, 0, 0, chartWidth, height, 12, "#10231c")
	text(&b, chartX, 42, "h", "#ffffff", strconv.Itoa(sum)+" "+a.noun)
	if a.subtitle != "" {
		text(&b, chartX, 66, "s", "#9fc9b4", a.subtitle)
	}
	if a.updated != "" {
		text(&b, chartWidth-chartX, 42, "u", "#9fc9b4", "updated "+a.updated)
	}
	b.WriteString(items.String())

	step := (chartWidth - 2*chartX) / len(a.months)
	barW := step * 2 / 3
	stripeW := 0
	if a.outline != "" {
		// The striped bar and the stack share the month's slot, opened first,
		// at the same width and touching.
		barW = step * 2 / 5
		stripeW = barW
	}
	for i, m := range a.months {
		sx := chartX + i*step + (step-barW-stripeW)/2
		mid := sx + (barW+stripeW)/2
		bx := sx
		if stripeW > 0 {
			bx = sx + stripeW
			if m.outline > 0 {
				h := m.outline * maxBar / peak
				if h == 0 {
					h = 1
				}
				rect(&b, sx, baseline-h, stripeW, h, 0, "url(#o)")
			}
		}
		top, total := baseline, 0
		for j, n := range m.counts {
			d := a.drawn(j, n)
			h := d * maxBar / peak
			if d > 0 && h == 0 {
				h = 1
			}
			if h == 0 {
				continue
			}
			top -= h
			if a.series[j] != a.scaled {
				total += n
			}
			rect(&b, bx, top, barW, h, 0, a.fill(j))
		}
		if top == baseline {
			rect(&b, bx, baseline-2, barW, 2, 0, "#2c4a3e")
		} else if total > 0 {
			text(&b, bx+barW/2, top-5, "n", "#ffffff", strconv.Itoa(total))
		}
		text(&b, mid, baseline+18, "m", "#9fc9b4", m.label)
	}
	b.WriteString("</svg>")
	alt := strings.ToUpper(a.noun[:1]) + a.noun[1:] + " per month, by repository"
	return "![" + alt + "](data:image/svg+xml;base64," + base64.StdEncoding.EncodeToString([]byte(b.String())) + ")\n"
}

// The chart is written straight into one builder: p/nt/svg formats each
// element with ufmt and appends it to a growing string, which cost this page
// close to a billion gas.

func rect(b *strings.Builder, x, y, w, h, r int, fill string) {
	b.WriteString(`<rect x="` + strconv.Itoa(x) + `" y="` + strconv.Itoa(y) + `" width="` + strconv.Itoa(w) +
		`" height="` + strconv.Itoa(h) + `" rx="` + strconv.Itoa(r) + `" fill="` + fill + `"/>`)
}

// text writes s as SVG text; callers pass repository names and numbers, so it
// escapes the three characters that could break the markup.
func text(b *strings.Builder, x, y int, class, fill, s string) {
	s = strings.NewReplacer("&", "&amp;", "<", "&lt;", ">", "&gt;").Replace(s)
	b.WriteString(`<text x="` + strconv.Itoa(x) + `" y="` + strconv.Itoa(y) + `" class="` + class + `" fill="` + fill + `">` + s + `</text>`)
}

// The area chart is a ring of one number per area, from the "areas" section,
// which reads, lines split by ";":
//
//	title pull requests by area
//	subtitle merged into gnolang/gno
//	updated 2026-09-24
//	slice 26 Docs
//	slice 17 GnoVM

const areasSlot = "areas"

var areaFills = []string{"#3ddc97", "#7aa2ff", "#c084fc", "#f472b6", "#2dd4bf", "#fb923c"}

type slice struct {
	label string
	count int
}

func parseAreas(spec string) (noun, subtitle, updated string, slices []slice) {
	for _, line := range strings.Split(strings.ReplaceAll(spec, "\n", ";"), ";") {
		line = strings.TrimSpace(line)
		switch {
		case strings.HasPrefix(line, "title "):
			noun = strings.TrimSpace(line[6:])
		case strings.HasPrefix(line, "subtitle "):
			subtitle = strings.TrimSpace(line[9:])
		case strings.HasPrefix(line, "updated "):
			updated = formatDay(strings.TrimSpace(line[8:]))
		case strings.HasPrefix(line, "slice "):
			n, label, ok := strings.Cut(strings.TrimSpace(line[6:]), " ")
			c, err := strconv.Atoi(n)
			if ok && err == nil && c > 0 && strings.TrimSpace(label) != "" {
				slices = append(slices, slice{strings.TrimSpace(label), c})
			}
		}
	}
	return noun, subtitle, updated, slices
}

// renderAreas draws the "areas" section as a ring, or "" when it holds no slice.
func renderAreas() string {
	noun, subtitle, updated, slices := parseAreas(Get(areasSlot))
	if len(slices) == 0 || noun == "" {
		return ""
	}
	total := 0
	for _, s := range slices {
		total += s.count
	}
	const height, cx, cy, r = 300, 140, 190, 80
	var b strings.Builder
	b.WriteString(`<svg xmlns="http://www.w3.org/2000/svg" width="720" height="300" viewBox="0 0 720 300">`)
	b.WriteString("<style>.h{font:700 26px sans-serif}.s{font:13px sans-serif}.t{font:700 34px sans-serif;text-anchor:middle}" +
		".c{font:13px sans-serif;text-anchor:middle}.l{font:15px sans-serif}.p{font:13px sans-serif;text-anchor:end}" +
		".u{font:12px sans-serif;text-anchor:end}</style>")
	rect(&b, 0, 0, chartWidth, height, 12, "#10231c")
	text(&b, chartX, 42, "h", "#ffffff", strings.ToUpper(noun[:1])+noun[1:])
	if subtitle != "" {
		text(&b, chartX, 66, "s", "#9fc9b4", subtitle)
	}
	if updated != "" {
		text(&b, chartWidth-chartX, 42, "u", "#9fc9b4", "updated "+updated)
	}
	// Each slice is a circle stroke whose dash covers its share of a ring
	// measured as 1000 units, rotated so the first slice starts at the top.
	start := 0
	for i, s := range slices {
		share := s.count * 1000 / total
		if i == len(slices)-1 {
			share = 1000 - start
		}
		b.WriteString(`<circle cx="` + strconv.Itoa(cx) + `" cy="` + strconv.Itoa(cy) + `" r="` + strconv.Itoa(r) +
			`" fill="none" stroke="` + areaFills[i%len(areaFills)] + `" stroke-width="34" pathLength="1000"` +
			` stroke-dasharray="` + strconv.Itoa(share) + ` 1000" stroke-dashoffset="` + strconv.Itoa(-start) +
			`" transform="rotate(-90 ` + strconv.Itoa(cx) + ` ` + strconv.Itoa(cy) + `)"/>`)
		start += share
	}
	text(&b, cx, cy+8, "t", "#ffffff", strconv.Itoa(total))
	text(&b, cx, cy+28, "c", "#9fc9b4", "merged")
	for i, s := range slices {
		y := 130 + i*30
		rect(&b, 280, y-12, 14, 14, 3, areaFills[i%len(areaFills)])
		text(&b, 304, y, "l", "#ffffff", s.label)
		text(&b, chartWidth-chartX-60, y, "p", "#ffffff", strconv.Itoa(s.count))
		text(&b, chartWidth-chartX, y, "p", "#9fc9b4", strconv.Itoa(s.count*100/total)+"%")
	}
	b.WriteString("</svg>")
	return "![" + mdText(strings.ToUpper(noun[:1])+noun[1:]+", "+subtitle) + "](data:image/svg+xml;base64," + base64.StdEncoding.EncodeToString([]byte(b.String())) + ")\n"
}

package home

import (
	"encoding/base64"
	"strconv"
	"strings"
)

// The hearts wall draws one red heart per address that sent one, row by row,
// with the slots still free in the last row left as outlines. Past
// wallCols*wallMaxRows hearts the wall stays full and a line under it counts
// the rest, so the image never grows past ten rows.

const (
	wallCols    = 24
	wallMaxRows = 10
	wallCell    = 28
	heartRed    = "#e63946"
	heartPath   = "M12 21C12 21 3 15.5 3 9.5 3 6.5 5.4 4 8.3 4 10 4 11.2 5 12 6.2 12.8 5 14 4 15.7 4 18.6 4 21 6.5 21 9.5 21 15.5 12 21 12 21Z"
)

// renderHeartsWall returns the wall as a markdown image; with no heart yet it
// is one row of empty slots.
func renderHeartsWall() string {
	n := Hearts()
	shown := n
	if limit := wallCols * wallMaxRows; shown > limit {
		shown = limit
	}
	rows := shown/wallCols + 1
	if rows > wallMaxRows {
		rows = wallMaxRows
	}
	w := 24 + wallCols*wallCell
	h := 24 + rows*wallCell
	more := n - shown
	if more > 0 {
		h += 26
	}
	var b strings.Builder
	b.WriteString(`<svg xmlns="http://www.w3.org/2000/svg" width="` + strconv.Itoa(w) + `" height="` + strconv.Itoa(h) +
		`" viewBox="0 0 ` + strconv.Itoa(w) + ` ` + strconv.Itoa(h) + `"><defs><path id="h" d="` + heartPath + `"/></defs>`)
	b.WriteString(`<rect width="` + strconv.Itoa(w) + `" height="` + strconv.Itoa(h) + `" rx="12" fill="#10231c"/>`)
	for i := 0; i < rows*wallCols; i++ {
		x := 14 + (i%wallCols)*wallCell
		y := 14 + (i/wallCols)*wallCell
		style := `fill="` + heartRed + `"`
		if i >= shown {
			style = `fill="none" stroke="#6b8f7f" stroke-width="1.5"`
		}
		b.WriteString(`<use href="#h" x="` + strconv.Itoa(x) + `" y="` + strconv.Itoa(y) + `" ` + style + `/>`)
	}
	if more > 0 {
		b.WriteString(`<text x="` + strconv.Itoa(w/2) + `" y="` + strconv.Itoa(h-14) + `" text-anchor="middle" ` +
			`fill="#9fc9b4" style="font:13px sans-serif">and ` + strconv.Itoa(more) + ` more</text>`)
	}
	b.WriteString("</svg>")
	return "![" + strconv.Itoa(n) + " hearts](data:image/svg+xml;base64," + base64.StdEncoding.EncodeToString([]byte(b.String())) + ")\n"
}

// Package home is David G.'s profile page on gno.land.
//
// gnoweb renders a profile by calling Render("") on the realm at exactly
// /r/<address>/home, so this path carries no /vN suffix.
//
// The page is a list of sections, each a markdown body the owner edits with
// one Set transaction, so changing the text never needs a redeploy. The slot
// named "order" lists the sections to show. Six sections are drawn rather
// than stored: "hero", the page banner, "banner" and "reviews", the activity
// charts, "areachart", the ring of pull requests by area, "game", today's
// Gnordle, and "hearts", the heart count and wall.
package home

import (
	"strconv"
	"strings"

	"chain/runtime"

	"gno.land/p/nt/avl/v0"
)

// admin is the only address allowed to edit sections.
const admin = address("g1rayfgklwl0aspz488wvrcrvt7t2quy6q06lgk2")

const (
	home       = "/r/g1rayfgklwl0aspz488wvrcrvt7t2quy6q06lgk2/home"
	orderSlot  = "order"
	maxNameLen = 32
	// maxPathLen is far above any link the page writes, and turns a long
	// crafted link away before the query parser, whose cost grows with it.
	maxPathLen = 256
)

var (
	slots  = avl.NewTree() // section name -> markdown body
	hearts = avl.NewTree() // address -> block height of the heart
)

func init() {
	for _, s := range defaultSlots {
		slots.Set(s.name, s.body)
	}
}

// Set writes one section of the page. Only the admin can call it.
//
// name is the section to write and body is its markdown. The text sections are
// "header", the bio at the top, then "gno", "projects", "peerdev" and
// "unrelated"; any other name creates a new section.
//
// name "order" decides which sections show and in which order. Its body lists
// every section name, comma separated, with no spaces. A name left out of the
// list is hidden, so copy the current list, from Get("order"), and edit it.
//
// name "herotext" is the banner's text: "key value" pairs split by ";", with
// the keys kicker, the small line on top, title, subtitle, tagline, footline,
// the small line at the bottom, and alt, the banner's description for screen
// readers. A key left out keeps its current default.
//
// "hero", "banner", "reviews", "areachart", "game" and "hearts" are drawn by
// the page itself: they cannot be set, only placed through "order".
//
// Examples, as the two fields of the form:
//
//	name: header
//	body: I'm a developer engineer at [Samouraï Coop](https://www.samourai.world/).
//
//	name: herotext
//	body: title David G.; subtitle Developer engineer at Samouraï Coop; footline Open for contribution
//
//	name: talks
//	body: ## Talks
//
//	name: order
//	body: hero,header,activityhead,banner,reviews,gno,areachart,projects,peerdev,unrelated,talks,game,hearts
func Set(cur realm, name, body string) {
	assertAdmin(cur)
	if name == "" || len(name) > maxNameLen || strings.ContainsAny(name, ", \n") {
		panic("invalid section name")
	}
	if drawnSections[name] {
		panic("reserved section: " + name)
	}
	slots.Set(name, body)
}

// SetActivity refreshes the three charts in one transaction. Only the admin
// can call it. Its three arguments are the bodies of the "activity",
// "reviewactivity" and "areas" sections, as scripts/activity.py prints them;
// an empty argument leaves that chart as it is.
func SetActivity(cur realm, activity, reviews, areas string) {
	assertAdmin(cur)
	for _, s := range []struct{ name, body string }{
		{activitySlot, activity},
		{reviewActivitySlot, reviews},
		{areasSlot, areas},
	} {
		if s.body != "" {
			slots.Set(s.name, s.body)
		}
	}
}

// Delete removes one section. Only the admin can call it.
//
// name is the section to remove, "talks" for example. Its name can stay in
// "order": a name with no section shows nothing.
func Delete(cur realm, name string) {
	assertAdmin(cur)
	if _, ok := slots.Remove(name); !ok {
		panic("no such section: " + name)
	}
}

// Get returns a section's markdown, or "" when it does not exist.
// Get("order") returns the current section list, the one to edit before
// setting "order".
func Get(name string) string {
	if v := slots.Get(name); v != nil {
		return v.(string)
	}
	return ""
}

// Heart records one heart from the caller. Each address can send exactly one.
func Heart(cur realm) {
	from := cur.Previous().Address().String()
	if hearts.Has(from) {
		panic("already sent: one heart per address")
	}
	hearts.Set(from, runtime.ChainHeight())
}

// Hearts returns how many distinct addresses sent a heart.
func Hearts() int { return hearts.Size() }

// HasHeart reports whether addr already sent a heart.
func HasHeart(addr address) bool { return hearts.Has(addr.String()) }

func assertAdmin(cur realm) {
	if cur.Previous().Address() != admin {
		panic("unauthorized")
	}
}

// Render serves:
//
//	""             the profile page
//	"wordle/..."   the Gnordle game
//	"hearts[/<n>]" the addresses that sent a heart, heartsPerPage per page
func Render(path string) string {
	if len(path) > maxPathLen {
		return "# Not found\n\n[Back home](" + home + ")\n"
	}
	// Only the game reads a query; elsewhere one is dropped, so a shared link
	// carrying ?utm_source=... still shows the page.
	if !strings.HasPrefix(path, "wordle") {
		path, _, _ = strings.Cut(path, "?")
	}
	switch {
	case path == "":
		return renderPage()
	case path == "wordle" || strings.HasPrefix(path, "wordle/") || strings.HasPrefix(path, "wordle?"):
		return renderWordle(path)
	case path == "hearts" || strings.HasPrefix(path, "hearts/"):
		return renderHearts(strings.TrimPrefix(strings.TrimPrefix(path, "hearts"), "/"))
	}
	return "# Not found\n\n[Back home](" + home + ")\n"
}

func renderPage() string {
	var b strings.Builder
	for _, name := range strings.Split(Get(orderSlot), ",") {
		switch name = strings.TrimSpace(name); name {
		case "":
		case "hero":
			b.WriteString(heroImage())
		case "areachart":
			b.WriteString(renderAreas())
		case "banner":
			b.WriteString(renderChart(activitySlot))
		case "reviews":
			b.WriteString(renderChart(reviewActivitySlot))
		case "game":
			b.WriteString(renderGameTeaser())
		case "hearts":
			b.WriteString(renderHeartsTeaser())
		default:
			b.WriteString(Get(name))
		}
		b.WriteString("\n\n")
	}
	b.WriteString("---\n\nThis page is a contract: [gno.land" + home + "](" + home + "$source).\n")
	return b.String()
}

func renderHeartsTeaser() string {
	return "## Hearts\n\n**" + strconv.Itoa(Hearts()) + "** so far. " +
		"[Send one](" + home + "$help&func=Heart): one transaction, one per address, " +
		"forever on chain. [See who did](" + home + ":hearts).\n\n" + renderHeartsWall()
}

// drawnSections are rendered from code and state, so Set refuses their names.
var drawnSections = map[string]bool{
	"hero": true, "banner": true, "reviews": true, "areachart": true, "game": true, "hearts": true,
}

// heroSlot holds the banner's text, one "key value" pair per field, split by
// ";": kicker, title, subtitle, tagline, footline and alt, the image's
// description. A field the section leaves out keeps its value from hero.
const heroSlot = "herotext"

func currentHero() heroText {
	h := hero
	for _, pair := range strings.Split(Get(heroSlot), ";") {
		key, value, _ := strings.Cut(strings.TrimSpace(pair), " ")
		value = strings.TrimSpace(value)
		switch key {
		case "kicker":
			h.kicker = value
		case "title":
			h.title = value
		case "subtitle":
			h.subtitle = value
		case "tagline":
			h.tagline = value
		case "footline":
			h.footline = value
		case "alt":
			h.alt = value
		}
	}
	return h
}

// mdText keeps s from closing a markdown link or image label.
func mdText(s string) string {
	return strings.NewReplacer("[", "(", "]", ")").Replace(s)
}

// xmlText escapes s for SVG text and attributes.
func xmlText(s string) string {
	return strings.NewReplacer("&", "&amp;", "<", "&lt;", ">", "&gt;", "\"", "&quot;", "'", "&#39;").Replace(s)
}

// heartsPerPage keeps one page of the list far under the query gas limit,
// which a list of every heart would pass at about 15,000 of them.
const heartsPerPage = 100

func renderHearts(page string) string {
	n := 1
	if page != "" {
		v, err := strconv.Atoi(page)
		if err != nil || v < 1 {
			return "# Hearts\n\nThere is no such page.\n\n[Back home](" + home + ")\n"
		}
		n = v
	}
	pages := (hearts.Size() + heartsPerPage - 1) / heartsPerPage
	if n > 1 && n > pages {
		return "# Hearts\n\nThere is no such page.\n\n[Back home](" + home + ")\n"
	}
	var b strings.Builder
	b.WriteString("# Hearts\n\n")
	if hearts.Size() == 0 {
		b.WriteString("Nobody yet. [Be the first](" + home + "$help&func=Heart).\n")
	}
	hearts.IterateByOffset((n-1)*heartsPerPage, heartsPerPage, func(addr string, h any) bool {
		b.WriteString("- " + addr + ", block " + strconv.FormatInt(h.(int64), 10) + "\n")
		return false
	})
	if pages > 1 {
		b.WriteString("\nPage " + strconv.Itoa(n) + " of " + strconv.Itoa(pages) + ".")
		if n > 1 {
			b.WriteString(" [Previous](" + home + ":hearts/" + strconv.Itoa(n-1) + ")")
		}
		if n < pages {
			b.WriteString(" [Next](" + home + ":hearts/" + strconv.Itoa(n+1) + ")")
		}
		b.WriteString("\n")
	}
	b.WriteString("\n[Back home](" + home + ")\n")
	return b.String()
}

